<?php require __DIR__.'/app/bootstrap.php';$u=require_user(false);require_commerce();$order=order_record((int)param('id'),$u);if((int)$order['customer_id']!==(int)$u['id']&&$u['role']!=='admin')go('seller/order.php?id='.$order['id']);$items=all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]);$title='Order '.$order['reference'];require ROOT.'/app/header.php'; ?>
<main class="page shell medium" id="main"><div class="dash-header"><h1>Order <?=e($order['reference'])?></h1><a class="pill" href="<?=e(url('orders.php'))?>">← My Orders</a></div><section class="panel padded"><?php render_order_summary($order,$items); ?><?php if($order['note']): ?><p><strong>Your note:</strong> <?=e($order['note'])?></p><?php endif ?></section><?php if($order['status']==='completed' && (int)$u['id']===(int)$order['customer_id'] && $u['role']!=='admin' && (int)$u['id']!==(int)$order['seller_id']): ?><section class="panel padded space-top"><h2>How was your food?</h2><p>Your review stays with the dish when it reappears and on the shop’s profile even if the dish is removed.</p><?php foreach($items as $item): ?><div class="checkout-item"><span><?=e($item['name'])?></span><a class="pill compact" href="<?=e(url('review-food.php?item='.$item['id']))?>">Review Food</a></div><?php endforeach ?></section><?php endif ?></main><?php require ROOT.'/app/footer.php'; ?>
